def lvl(P):
    a, k, (m, n) = P['a'], P['k'], P['mn']; f = lambda x: '\\(%s\\)' % x
    o1 = M4(1, '\\(|\\vec a|=%d\\). Then \\(|%s\\vec a|=\\)…' % (a, fr(k)), '\\(|\\vec a|=%d\\). Khi đó \\(|%s\\vec a|=\\)…' % (a, fr(k)), f(fr(abs(k) * a)), [f(fr(-abs(k) * a)), f(fr(abs(k) * a + a)), f(str(a)), f(fr(abs(k) * a - a))], '\\(|k\\vec a|=|k||\\vec a|\\).', '\\(|k\\vec a|=|k||\\vec a|\\).')
    x = F(n - m, n); o2 = M4(2, 'M is on side BC with \\(\\overrightarrow{BM}=\\dfrac{%d}{%d}\\overrightarrow{BC}\\). Then \\(\\overrightarrow{AM}=y\\overrightarrow{AB}+z\\overrightarrow{AC}\\) with \\(z=\\)…' % (m, n), 'Điểm M thuộc cạnh BC với \\(\\overrightarrow{BM}=\\dfrac{%d}{%d}\\overrightarrow{BC}\\). Khi đó \\(\\overrightarrow{AM}=y\\overrightarrow{AB}+z\\overrightarrow{AC}\\) với \\(z=\\)…' % (m, n), f(fr(F(m, n))), [f(fr(x)), f(fr(F(m, n) + 1)), f(fr(-F(m, n)))], '\\(\\overrightarrow{AM}=(1-t)\\overrightarrow{AB}+t\\overrightarrow{AC}\\) with \\(t=\\dfrac{%d}{%d}\\).' % (m, n), '\\(\\overrightarrow{AM}=(1-t)\\overrightarrow{AB}+t\\overrightarrow{AC}\\) với \\(t=\\dfrac{%d}{%d}\\).' % (m, n))
    kk = P['kk']; o3 = M4(3, '\\(\\overrightarrow{PQ}=%d\\,\\overrightarrow{PR}\\). Then \\(\\overrightarrow{PR}=k\\,\\overrightarrow{PQ}\\) with \\(k=\\)…' % kk, '\\(\\overrightarrow{PQ}=%d\\,\\overrightarrow{PR}\\). Khi đó \\(\\overrightarrow{PR}=k\\,\\overrightarrow{PQ}\\) với \\(k=\\)…' % kk, f(fr(F(1, kk))), [f(str(kk)), f(str(-kk)), f(fr(F(-1, kk)))], 'Divide both sides by %d.' % kk, 'Chia hai vế cho %d.' % kk)
    t4 = tf(4, 'G is the centroid of triangle ABC. \\(%s+%s+%s=\\vec0\\).' % (ov('G', 'A'), ov('G', 'B'), ov('G', P['t4'])), 'G là trọng tâm tam giác ABC. \\(%s+%s+%s=\\vec0\\).' % (ov('G', 'A'), ov('G', 'B'), ov('G', P['t4'])), P['t4'] == 'C', 'The centroid satisfies \\(\\overrightarrow{GA}+\\overrightarrow{GB}+\\overrightarrow{GC}=\\vec0\\).', 'Trọng tâm thỏa \\(\\overrightarrow{GA}+\\overrightarrow{GB}+\\overrightarrow{GC}=\\vec0\\).')
    c5 = P['t5']; t5 = tf(5, 'If \\(\\vec b=%s\\vec a\\) with \\(\\vec a\\ne\\vec0\\), then \\(\\vec b\\) and \\(\\vec a\\) have %s direction.' % (fr(c5[0]), 'the same' if c5[1] else 'opposite'), 'Nếu \\(\\vec b=%s\\vec a\\) với \\(\\vec a\\ne\\vec0\\) thì \\(\\vec b\\) và \\(\\vec a\\) %s.' % (fr(c5[0]), 'cùng hướng' if c5[1] else 'ngược hướng'), (c5[0] > 0) == c5[1], 'The sign of \\(k\\) decides the direction.', 'Dấu của \\(k\\) quyết định hướng.')
    q = P['q']; s6 = sh(6, '\\(|\\vec a|=%d\\). Find \\(|%s\\vec a|\\).' % (q[0], fr(q[1])), 'Cho \\(|\\vec a|=%d\\). Tính \\(|%s\\vec a|\\).' % (q[0], fr(q[1])), fr(abs(q[1]) * q[0]), '\\(|k||\\vec a|=%s\\cdot%d\\).' % (fr(abs(q[1])), q[0]), '\\(|k||\\vec a|=%s\\cdot%d\\).' % (fr(abs(q[1])), q[0]))
    w = P['w']; s7 = sh(7, 'In triangle ABC with centroid G, the median AI has length %d. Find AG.' % w, 'Tam giác ABC có trọng tâm G, trung tuyến AI dài %d. Tính AG.' % w, fr(F(2 * w, 3)), 'G divides AI so that \\(AG=\\dfrac23AI\\).', 'G chia AI sao cho \\(AG=\\dfrac23AI\\).')
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
PP = [dict(a=6, k=F(-3), mn=(1, 4), kk=3, t4='C', t5=(F(-2), False), q=(4, F(5)), w=9), dict(a=8, k=F(5), mn=(2, 5), kk=-2, t4='B', t5=(F(3), True), q=(10, F(-3, 2)), w=12), dict(a=12, k=F(-1, 2), mn=(3, 7), kk=4, t4='A', t5=(F(-1, 3), True), q=(9, F(-4, 3)), w=15)]
